/**
 * ERM3 ETF register — the ETFs ERM3 prices into its ETF return store
 * (market, sectors, subsectors, style, macro sleeves, broad-market price
 * coverage, proxies). Committed mirror at `mcp/data/etf_register.json`,
 * generated by `scripts/export_etf_register_json.py` from ERM3's
 * `erm3/shared/etf_register.py`.
 *
 * Together with the ETF catalog (`lib/dal/etf-catalog.ts`) it lets an endpoint
 * tell a known fund it cannot price apart from a ticker on no list (RMAPI-14).
 */

import registerJson from "@/mcp/data/etf_register.json";
import { lookupEtfTicker } from "@/lib/dal/etf-catalog";

interface EtfRegisterDoc {
  etfs: Record<string, { role: string }>;
}

const REGISTER = (registerJson as EtfRegisterDoc).etfs ?? {};

/** Factor role in the ERM3 register (market, sector, subsector, style, macro:<cat>, broad_market, proxy), or null. */
export function etfRegisterRole(ticker: string): string | null {
  return REGISTER[(ticker ?? "").trim().toUpperCase()]?.role ?? null;
}

/** True when ERM3 prices this ETF (it is on the register). */
export function isRegisteredEtf(ticker: string): boolean {
  return etfRegisterRole(ticker) !== null;
}

/** True when the ticker is a known ETF: on the ERM3 register or in the ETF catalog. */
export function isKnownEtf(ticker: string): boolean {
  return isRegisteredEtf(ticker) || lookupEtfTicker(ticker) !== null;
}
